package net.zartra.gui;
import org.junit.Test;import static org.junit.Assert.*;
public class Goal2RuntimeSupportTest {@Test public void paginationRejectsInvalidContentSlots(){MenuDefinition m=new MenuDefinition("m","M",2);m.paginationContentSlots.add(1);m.paginationContentSlots.add(1);assertFalse(MenuPagination.valid(m));m.paginationContentSlots.clear();m.paginationContentSlots.add(99);assertFalse(MenuPagination.valid(m));m.paginationContentSlots.clear();m.paginationContentSlots.add(1);assertTrue(MenuPagination.valid(m));}@Test public void vaultValidationIsSafeWhenUnavailable(){assertTrue(VaultAdapter.validAmount("0"));assertFalse(VaultAdapter.validAmount("-1"));assertFalse(VaultAdapter.validAmount("NaN"));assertTrue(VaultAdapter.validNode("example.permission"));assertFalse(VaultAdapter.validNode("bad node"));}}